def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    last_my, last_opp = history[-1]

    if opp_def > n * 0.4:
        if last_opp == 'D':
            if last_my == 'D':
                if rng.random() < 0.2:
                    return 'C'
                return 'D'
            return 'D'
        else:
            return 'C'

    ret = 0
    forg = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i+1][1] == 'D':
                ret += 1
            else:
                forg += 1

    if forg >= 2 and ret == 0:
        if last_opp == 'C':
            return 'D'
        else:
            return 'D'

    if ret > 0:
        if n >= 99:
            return 'D'
        if last_opp == 'C':
            return 'C'
        else:
            if last_my == 'D' and rng.random() < 0.3:
                return 'C'
            return 'D'

    if opp_def == 0:
        if n == 1 and forg == 0:
            return 'D'
        if n == 4 and forg == 1:
            return 'D'

    if n >= 1 and history[-1][0] == 'D':
        return 'C'
    if n >= 2 and history[-2][0] == 'D':
        return 'C'

    if n >= 95:
        if last_opp == 'C':
            return 'D'
        else:
            if n >= 99:
                return 'D'
            if last_my == 'D' and rng.random() < 0.1:
                return 'C'
            return 'D'

    if last_opp == 'C':
        return 'C'
    else:
        if last_my == 'D' and rng.random() < 0.3:
            return 'C'
        return 'D'
